"use client";

import { useState } from "react";

import { SmoothInput } from "./smooth-caret-input-skiperui";

interface FormData {
  name: string;
  email: string;
  message: string;
}

export function ContactForm() {
  const [formData, setFormData] = useState<FormData>({
    name: "",
    email: "",
    message: "",
  });

  return (
    <div className="mx-auto max-w-md space-y-6">
      <div className="space-y-4">
        <SmoothInput
          placeholder="Your name"
          value={formData.name}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, name: e.target.value }))
          }
          wrapperClassName="max-w-none"
          aria-label="Name"
        />
        <SmoothInput
          placeholder="Your email"
          value={formData.email}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, email: e.target.value }))
          }
          wrapperClassName="max-w-none"
          aria-label="Email"
        />
        <SmoothInput
          placeholder="Your message"
          value={formData.message}
          onChange={(e) =>
            setFormData((prev) => ({ ...prev, message: e.target.value }))
          }
          wrapperClassName="max-w-none"
          aria-label="Message"
        />
      </div>
      <div className="flex justify-end gap-3">
        <button
          type="button"
          onClick={() =>
            setFormData({ name: "", email: "", message: "" })
          }
          className="cursor-pointer rounded-xl bg-[#f4f4f5] px-5 py-2.5 text-sm font-medium text-[#18181b] transition-all hover:bg-[#e4e4e7] active:scale-[0.97] dark:bg-[#27272a] dark:text-[#fafafa] dark:hover:bg-[#3f3f46]"
        >
          Clear
        </button>
        <button
          type="button"
          onClick={() =>
            alert(
              `Name: ${formData.name}\nEmail: ${formData.email}\nMessage: ${formData.message}`,
            )
          }
          className="cursor-pointer rounded-xl bg-[#18181b] px-5 py-2.5 text-sm font-medium text-[#fafafa] transition-all hover:bg-[#27272a] active:scale-[0.97] dark:bg-[#fafafa] dark:text-[#18181b] dark:hover:bg-[#e4e4e7]"
        >
          Submit
        </button>
      </div>
    </div>
  );
}

