              Vertical Tabs ΓÇö Animated Service Showcase
            </h2>
            <p className="mb-8 text-xs text-[#646b75] dark:text-[#9a958a]">
              Tab navigation with smooth animated transitions and auto-play
            </p>
          </div>
          <VerticalTabs />
        </section>
      )}

      {/* ΓöÇΓöÇΓöÇ Interactive Selector Showcase ΓöÇΓöÇΓöÇ */}
      {show("interactive") && (
        <section className="border-t border-[#e3e7ec] dark:border-[#2b2a25]">
          <div className="mx-auto max-w-6xl px-4 pt-24 text-center">
            <h2 className="mb-4 text-sm font-medium uppercase tracking-[0.2em] text-[#646b75] dark:text-[#9a958a]">
              Interactive Selector ΓÇö Expandable Options
            </h2>
            <p className="mb-8 text-xs text-[#646b75] dark:text-[#9a958a]">
              Click to expand each option with smooth animated transitions
            </p>
          </div>
          <InteractiveSelector />
        </section>
      )}

      {/* ΓöÇΓöÇΓöÇ Contact Form Showcase ΓöÇΓöÇΓöÇ */}
      {show("forms") && (
        <section className="border-t border-[#e3e7ec] dark:border-[#2b2a25] py-24">
          <div className="mx-auto max-w-6xl px-4 text-center">
            <h2 className="mb-4 text-sm font-medium uppercase tracking-[0.2em] text-[#646b75] dark:text-[#9a958a]">
              Contact Form ΓÇö Smooth Caret Input
            </h2>
            <p className="mb-8 text-xs text-[#646b75] dark:text-[#9a958a]">
              Custom animated caret that springs to each cursor position
            </p>
            <ContactForm />
          </div>
        </section>
      )}

      {/* ΓöÇΓöÇΓöÇ Footer Showcase ΓöÇΓöÇΓöÇ */}
      {show("footer") && (
        <section>
          <Footer4Col />
        </section>
